function parseCents(value) {
  if (typeof value !== "string") return null;
  const s = value.trim();
  if (s === "") return null;
  if (!/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(s)) return null;
  const parts = s.split(".");
  const whole = parts[0];
  const frac = parts[1] || "";
  const centsStr = whole + (frac + "00").slice(0, 2);
  const cents = Number(centsStr);
  if (!Number.isSafeInteger(cents)) return null;
  return cents;
}

